const payload = $input.first().json;
const lead = payload.lead || {};

const prompt = [
  'You are scoring a Speed-to-Lead demo inquiry for MVella Studios.',
  'Return JSON only with keys:',
  'score (integer 1-10), summary (one paragraph), urgency (low|medium|high), opener (one spoken sentence AFTER recording consent).',
  '',
  'Name: ' + (lead.name || ''),
  'Phone: ' + (lead.phone || ''),
  'Service: ' + (lead.service_type || ''),
  'Description: ' + (lead.description || ''),
].join('\n');

let qualification = {
  score: 5,
  summary: 'Model unavailable — proceeding with a default mid score.',
  urgency: 'medium',
  opener: '',
};

try {
  const claude = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      model: $env.ANTHROPIC_MODEL || 'claude-sonnet-4-5',
      max_tokens: 800,
      messages: [{ role: 'user', content: prompt }],
    }),
  });
  const text = claude?.content?.[0]?.text || (typeof claude === 'string' ? claude : '');
  const match = String(text).match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    qualification = {
      score: Number(parsed.score) || 5,
      summary: String(parsed.summary || qualification.summary),
      urgency: String(parsed.urgency || 'medium'),
      opener: String(parsed.opener || ''),
    };
  }
} catch (error) {
  qualification.summary = 'Claude scoring failed: ' + (error.message || 'unknown error');
}

return [{ json: { ...payload, qualification } }];

const intake = $('Lead intake').first().json;
const scored = $('Qualify with Claude').first().json;
const lead = intake.lead;
const vapi = intake.vapi || {};

const firstMessage = String(vapi.firstMessage || '')
  .replaceAll('{{name}}', lead.name)
  .replaceAll('{{serviceType}}', lead.service_type);

const body = {
  phoneNumberId: $env.VAPI_PHONE_NUMBER_ID,
  customer: { number: lead.phone, name: lead.name },
  metadata: { leadId: lead.id },
  assistant: {
    name: 'MVella Speed-to-Lead',
    firstMessage,
    firstMessageMode: 'assistant-speaks-first',
    recordingEnabled: true,
    maxDurationSeconds: 180,
    voicemailDetection: { provider: 'vapi', enabled: true },
    model: {
      provider: 'anthropic',
      model: $env.ANTHROPIC_MODEL || 'claude-sonnet-4-5',
      messages: [{ role: 'system', content: vapi.systemPrompt }],
    },
    voice: {
      provider: 'vapi',
      voiceId: $env.VAPI_VOICE_ID || 'Savannah',
    },
    analysisPlan: {
      structuredDataPlan: {
        enabled: true,
        schema: {
          type: 'object',
          properties: {
            recording_consent: {
              type: 'string',
              enum: ['granted', 'declined', 'unknown'],
            },
            preferred_start_iso: { type: 'string' },
            attendee_email: { type: 'string' },
            booked_intent: { type: 'boolean' },
          },
        },
      },
    },
    server: {
      url: vapi.serverUrl,
      secret: $env.VAPI_SERVER_SECRET || $env.DEMO_LEADS_WEBHOOK_SECRET,
      timeoutSeconds: 20,
    },
    variableValues: {
      name: lead.name,
      serviceType: lead.service_type,
    },
  },
};

const call = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.vapi.ai/call',
  headers: {
    Authorization: 'Bearer ' + $env.VAPI_API_KEY,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify(body),
});

if (intake.api?.leadUrl) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: intake.api.leadUrl,
      headers: {
        'Content-Type': 'application/json',
        'x-demo-leads-secret': $env.DEMO_LEADS_WEBHOOK_SECRET,
        Authorization: 'Bearer ' + $env.DEMO_LEADS_WEBHOOK_SECRET,
      },
      body: JSON.stringify({
        vapi_call_id: call.id || call?.call?.id || null,
        call_status: 'dialing',
        qualification_score: scored.qualification?.score,
        qualification_summary: scored.qualification?.summary,
        qualification_urgency: scored.qualification?.urgency,
      }),
    });
  } catch (error) {}
}

return [{ json: { ...intake, qualification: scored.qualification, vapiCall: call } }];

const prev = $input.first().json;
const callId = prev.vapiCall?.id || prev.vapiCall?.call?.id;
let call = {};

if (callId) {
  try {
    call = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.vapi.ai/call/' + callId,
      headers: { Authorization: 'Bearer ' + $env.VAPI_API_KEY },
    });
  } catch (error) {
    call = { error: error.message };
  }
}

const status = call.status || '';
const ended = call.endedReason || '';
const answered =
  status === 'in-progress' ||
  ['assistant-ended-call', 'customer-ended-call', 'silence-timed-out', 'exceeded-max-duration'].includes(ended);
const stillRinging = ['queued', 'ringing', 'dialing'].includes(status);
const noAnswer =
  stillRinging || ['customer-did-not-answer', 'voicemail', 'customer-busy'].includes(ended);
const shouldSendSms = !answered && (noAnswer || !status);

if (shouldSendSms && stillRinging && callId) {
  try {
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: 'https://api.vapi.ai/call/' + callId,
      headers: { Authorization: 'Bearer ' + $env.VAPI_API_KEY },
    });
  } catch (error) {}
}

return [{ json: { ...prev, vapiCallStatus: call, shouldSendSms } }];

const prev = $input.first().json;
const lead = prev.lead;
const bookingUrl = prev.vapi?.bookingUrl || $env.CAL_COM_BOOKING_URL || 'https://cal.com';
const sid = $env.TWILIO_ACCOUNT_SID;
const token = $env.TWILIO_AUTH_TOKEN;
const from = $env.TWILIO_FROM_NUMBER;
const auth = 'Basic ' + Buffer.from(sid + ':' + token).toString('base64');

const params = new URLSearchParams();
params.set('From', from);
params.set('To', lead.phone);
params.set(
  'Body',
  'Hi ' + lead.name + ', this is MVella Studios following up on your ' + lead.service_type +
    ' request. We tried calling. Book a time with Matthew: ' + bookingUrl
);

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.twilio.com/2010-04-01/Accounts/' + sid + '/Messages.json',
  headers: {
    Authorization: auth,
    'Content-Type': 'application/x-www-form-urlencoded',
  },
  body: params.toString(),
});

const now = new Date().toISOString();
await this.helpers.httpRequest({
  method: 'PATCH',
  url: prev.api.leadUrl,
  headers: {
    'Content-Type': 'application/json',
    'x-demo-leads-secret': $env.DEMO_LEADS_WEBHOOK_SECRET,
    Authorization: 'Bearer ' + $env.DEMO_LEADS_WEBHOOK_SECRET,
  },
  body: JSON.stringify({
    call_status: 'sms_sent',
    contact_channel: 'sms',
    sms_sent_at: now,
  }),
});

return [{ json: { ...prev, smsSent: true } }];
